SELECT percentile_cont(0.75) within GROUP (ORDER BY avg_systolic_bp) AS percentile_75 FROM (SELECT AVG(value) AS avg_systolic_bp FROM labevents JOIN icustays ON labevents.subject_id = icustays.subject_id WHERE itemid = 160 AND valueuom = 'mm[Hg]' AND EXTRACT(YEAR FROM charttime) = EXTRACT(YEAR FROM intime) AND EXTRACT(MONTH FROM charttime) = EXTRACT(MONTH FROM intime) AND EXTRACT(DAY FROM charttime) = EXTRACT(DAY FROM intime) AND (age(CURRENT_DATE, patient_dob) BETWEEN 77 AND 87) AND gender = 'F' AND (stay_length <= 48)) AS avg_bp;